-- Name: COLUMN bot_group_member.version; Type: COMMENT; Schema: nnmbot; Owner: -
--

COMMENT ON COLUMN nnmbot.bot_group_member.version IS '乐观锁版本号，避免并发签到或扣费覆盖余额';


--
-- 成员合并只保留一条 bot_group_member；该表保存旧主键到主成员的解析关系，供在途积分操作和缓存身份连续解析。
CREATE TABLE nnmbot.bot_group_member_merge (
    id bigint NOT NULL,
    group_id bigint NOT NULL,
    source_member_id bigint NOT NULL,
    target_member_id bigint NOT NULL,
    merged_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    -- 禁止成员合并到自身，避免旧主键解析形成自循环。
    CONSTRAINT ck_bot_group_member_merge_distinct CHECK (source_member_id <> target_member_id)
);

COMMENT ON TABLE nnmbot.bot_group_member_merge IS '逻辑群组成员合并后的旧主键解析记录，不代表第二条成员数据';
COMMENT ON COLUMN nnmbot.bot_group_member_merge.id IS '成员合并记录主键';
COMMENT ON COLUMN nnmbot.bot_group_member_merge.group_id IS '逻辑群组主键';
COMMENT ON COLUMN nnmbot.bot_group_member_merge.source_member_id IS '被合并成员的旧主键';
COMMENT ON COLUMN nnmbot.bot_group_member_merge.target_member_id IS '合并后的主成员主键';
COMMENT ON COLUMN nnmbot.bot_group_member_merge.merged_at IS '成员合并完成时间';

CREATE SEQUENCE nnmbot.bot_group_member_merge_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

ALTER SEQUENCE nnmbot.bot_group_member_merge_id_seq
    OWNED BY nnmbot.bot_group_member_merge.id;


