.brand { color: #e4f1f8; font-size: 11px; font-weight: 700; border-bottom: 1px solid rgba(255,255,255,.35); padding-bottom: 12px; }
.eyebrow { color: #f4d99d; font-size: 12px; margin: 35px 0 8px; }
