.art { position: absolute; top: 26px; right: 16px; width: 36%; height: 308px; object-fit: contain; filter: drop-shadow(0 20px 18px rgba(0,0,0,.7)); }
.content { padding: 0 32px 25px; background: #f7faf8; }
.metrics { display: grid; grid-template-columns: repeat(5,minmax(0,1fr)); padding: 24px 0 22px; gap: 18px 10px; border-bottom: 1px solid #dbe5df; }
.metric { min-width: 0; padding-left: 10px; }
.metric:nth-child(4n) { border-right: 0; }
.metric-label { color: #7c8e9b; font-size: 11px; overflow-wrap: anywhere; }
.metric-value { color: #278287; font-size: 28px; line-height: 1.45; font-weight: 600; overflow-wrap: anywhere; }
.metric:nth-child(4n+1) .metric-value { color: #bd596e; }
.metric:nth-child(4n+2) .metric-value { color: #3e80b7; }
.metric:nth-child(4n+4) .metric-value { color: #ad882f; }
.section-heading { display: flex; flex-wrap: wrap; align-items: baseline; justify-content: space-between; gap: 6px 12px; margin: 24px 0 16px; }
h2 { font-size: 17px; margin: 0; }
.section-heading span { font-size: 11px; color: #8194a1; }
.ability { display: grid; grid-template-columns: 64px minmax(0,1fr); gap: 18px; margin-bottom: 14px; padding: 18px; background: #fff; border-radius: 14px; border: 1px solid #e0e8e3; box-shadow: 0 8px 18px rgba(32,56,41,.12), inset 0 1px 0 #fff; }
.ability-art { width: 64px; height: 64px; object-fit: contain; background: #2c443a; border-radius: 14px; padding: 12px; color: white; text-align: center; }
.ability-heading { display: flex; align-items: baseline; justify-content: space-between; gap: 12px; margin-bottom: 5px; }
h3 { margin: 0; font-size: 15px; color: #2c5646; overflow-wrap: anywhere; }
.energy { color: #a46d28; font-size: 10px; flex-shrink: 0; border-left: 2px solid #d3b06d; padding-left: 8px; }
.ability p { margin: 0; color: #708491; font-size: 12px; line-height: 1.8; overflow-wrap: anywhere; }
.source { margin-top: 19px; color: #8999a5; font-size: 9px; overflow-wrap: anywhere; }
.empty { margin: 0; padding: 35px 0; color: #8194a1; }
footer { display: flex; justify-content: space-between; gap: 15px; padding: 15px 32px; background: #253a30; color: #c9dbce; font-size: 10px; overflow-wrap: anywhere; }
@media (max-width: 480px) {
  body { padding: 12px; }
  main { border-radius: 18px; }
  .hero { min-height: 308px; }
  .hero-content { padding: 23px 18px; width: 100%; padding-right: 109px; }
  .brand { font-size: 9px; }
  .eyebrow { margin-top: 28px; }
  h1 { font-size: 27px; }
  .art { width: 102px; height: 254px; right: 3px; top: 49px; }
  .description { font-size: 11px; }
  .content { padding: 0 15px 20px; }
  .metrics { grid-template-columns: repeat(3,minmax(0,1fr)); gap: 16px 5px; }
  .metric { padding-left: 4px; }
  .metric-value { font-size: 21px; }
  .ability { grid-template-columns: 42px minmax(0,1fr); gap: 12px; padding: 13px 12px; border-radius: 12px; }
  .ability-art { width: 42px; height: 42px; padding: 7px; border-radius: 10px; }
  .ability-heading { flex-wrap: wrap; gap: 2px 8px; }
  footer { padding: 13px 18px; flex-wrap: wrap; }
}
</style></head><body><main>
<article th:each="item : ${items}">
<header class="hero">
<img class="backdrop" alt="" th:if="${item[''iconUrl''] != null}" th:src="${item[''iconUrl'']}"/><div class="veil"></div>
<img class="art" alt="" th:if="${item[''iconUrl''] != null}" th:src="${item[''iconUrl'']}"/>
<div class="hero-content"><div class="brand">WARFRAME / NNMBOT</div><div class="eyebrow" th:text="${category}"></div>
<h1 th:text="${item.name}"></h1><p class="description" th:if="${item[''description''] != null and item[''description''] != ''''}" th:text="${item[''description'']}"></p></div>
</header>
<div class="content">
<div class="metrics" th:if="${item[''metrics''] != null and !#lists.isEmpty(item[''metrics''])}">
<div class="metric" th:each="metric : ${item[''metrics'']}"><div class="metric-label" th:text="${metric.label}"></div>
<div class="metric-value" th:text="${metric[''value''] != null ? metric[''value''] : ''未提供''}"></div></div>
</div>
<section th:if="${item[''abilities''] != null and !#lists.isEmpty(item[''abilities''])}">
<div class="section-heading"><h2>技能</h2><span th:text="${#lists.size(item[''abilities'']) + '' 项''}"></span></div>
<div class="ability" th:each="ability : ${item[''abilities'']}">
<img class="ability-art" alt="" th:if="${ability[''iconUrl''] != null}" th:src="${ability[''iconUrl'']}"/>
<span class="ability-art" th:if="${ability[''iconUrl''] == null}" th:text="${ability.order}"></span>
<div><div class="ability-heading"><h3 th:text="${ability.name}"></h3>
<span class="energy" th:if="${ability[''energy''] != null}" th:text="${ability[''energy''] + '' 能量''}"></span></div>
<p th:text="${ability[''description''] != null and ability[''description''] != '''' ? ability[''description''] : ''描述未提供''}"></p></div>
</div></section>
<div class="source" th:text="${item[''sourceCode''] != null ? ''资料来源 · '' + item[''sourceCode''] : ''资料来源未提供''}"></div>
</div></article>
<div class="content" th:if="${items == null or #lists.isEmpty(items)}"><p class="empty">没有找到匹配的装备</p></div>
<footer><span th:text="${page + ''/'' + totalPages + '' 页，共 '' + totalCount + '' 条''}"></span><span>WARFRAME · 装备档案</span></footer>
</main></body></html>
