.type { color: #a8bfb4; font-size: 10px; overflow-wrap: anywhere; }
.rerolled { color: #ecd194; font-size: 10px; flex-shrink: 0; border-left: 2px solid #b69a5e; padding-left: 7px; }
.prices { display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); gap: 12px; margin-top: 18px; }
.label { color: #afc6bb; font-size: 10px; }
.price { color: #86edce; font-size: 27px; line-height: 1.55; font-weight: 700; overflow-wrap: anywhere; }
.median { color: #edaac5; }
.unit { font-size: 10px; font-weight: 400; }
.details { display: grid; grid-template-columns: repeat(3,minmax(0,1fr)); gap: 9px; padding-top: 12px; margin-top: 11px; border-top: 1px solid rgba(173,206,191,.24); }
.details span { display: block; color: #d6e5dc; font-size: 12px; overflow-wrap: anywhere; }
.heat { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 5px 15px; margin-top: 12px; color: #a9c2b6; font-size: 10px; }
.heat strong { color: #e4cf91; font-weight: 600; overflow-wrap: anywhere; }
.empty { padding: 24px 0; color: #bfd2c9; overflow-wrap: anywhere; }
.notice { color: #ecd194; margin: 15px 0 0; font-size: 11px; overflow-wrap: anywhere; }
footer { position: relative; display: flex; justify-content: space-between; gap: 14px; padding: 15px 32px; background: rgba(16,27,23,.93); color: #b9d0c4; font-size: 10px; overflow-wrap: anywhere; }
@media (max-width: 480px) {
  body { padding: 12px; }
  main { border-radius: 18px; }
  .hero { min-height: 211px; }
  .hero-content { padding: 23px 18px; }
  .brand { font-size: 9px; }
  h1 { font-size: 27px; }
  .content { padding: 20px 15px; }
  .quote-grid { grid-template-columns: minmax(0,1fr); gap: 14px; }
  .quote { padding: 18px 17px 15px; border-radius: 14px; }
  .weapon { font-size: 16px; }
  .price { font-size: 26px; }
  footer { padding: 13px 18px; flex-wrap: wrap; }
}
</style></head><body><main>
<header class="hero"><div class="veil"></div>
<div class="hero-content"><div class="hero-top"><span class="brand">WARFRAME / NNMBOT</span>
<span class="platform" th:text="${platform != null ? #strings.toUpperCase(platform) : ''平台未提供''}"></span></div>
<h1>紫卡周成交统计</h1><div class="subtitle">Digital Extremes · 官方周统计</div>
<div class="snapshot"><span th:text="${stale ? ''历史成功快照'' : ''最近成功快照''}"></span>
<span th:if="${fetchedAtLabel != null}" th:text="${'' / '' + fetchedAtLabel}"></span></div></div></header>
<div class="content">
<div class="section-heading"><span th:text="${query != null and query != '''' ? query : ''武器成交记录''}"></span><span>单位 · 白金</span></div>
<div class="quote-grid">
<article class="quote" th:each="item : ${items}">
<div class="quote-heading"><div><div class="weapon" th:text="${item.weaponName}"></div><div class="type" th:text="${item.itemType}"></div></div>
<span class="rerolled" th:text="${item.rerolled ? ''已洗'' : ''未洗''}"></span></div>
<div class="prices"><div><div class="label">成交均价</div>
<div class="price" th:text="${item[''avg''] != null ? #numbers.formatDecimal(item[''avg''],1,1) : ''未提供''}"></div></div>
<div><div class="label">成交中位价</div><div class="price median" th:text="${item[''median''] != null ? #numbers.formatDecimal(item[''median''],1,1) : ''未提供''}"></div></div></div>
<div class="details"><div><div class="label">最低价</div><span th:text="${item[''min''] != null ? #numbers.formatDecimal(item[''min''],1,1) : ''未提供''}"></span></div>
<div><div class="label">最高价</div><span th:text="${item[''max''] != null ? #numbers.formatDecimal(item[''max''],1,1) : ''未提供''}"></span></div>
<div><div class="label">标准差</div><span th:text="${item[''stddev''] != null ? #numbers.formatDecimal(item[''stddev''],1,2) : ''未提供''}"></span></div></div>
<div class="heat"><span>相对交易热度</span><strong th:text="${item[''pop''] != null ? #numbers.formatDecimal(item[''pop''],1,4) : ''未提供''}"></strong></div>
</article>
</div>
<p class="notice" th:if="${notice != null}" th:text="${notice}"></p>
<div class="empty" th:if="${(items == null or #lists.isEmpty(items)) and notice == null}">没有找到匹配的周成交记录</div>
</div><footer><span th:text="${pagination}"></span><span>WARFRAME · 市场档案</span></footer>
</main></body></html>
', 'f', '2026-10-15 13:19:05.136139', '2026-10-15 13:19:05.136139'),
