('25', 'wf-relics-compact-v1', 'warframe.relics', 'Warframe 遗物明细', '35', '100', '
<!DOCTYPE html>
<html lang="zh-CN" xmlns:th="http://www.thymeleaf.org">
<head><meta charset="UTF-8"/><meta name="viewport" content="width=device-width, initial-scale=1"/>
<title>Warframe 遗物</title>
<style>
@page { size: 500px 1200px; margin: 0; }
* { box-sizing: border-box; letter-spacing: 0; }
body { margin: 0; background: #fff; color: #202626; font-family: "Noto Sans SC", "PingFang SC", sans-serif; font-size: 13px; line-height: 1.55; }
main { width: 100%; padding: 22px; }
header { border-bottom: 2px solid #2b7770; padding-bottom: 12px; }
.brand { color: #2b7770; font-size: 11px; font-weight: bold; }
h1 { margin: 4px 0; font-size: 24px; line-height: 1.35; word-wrap: break-word; }
.meta { color: #66716e; font-size: 12px; word-wrap: break-word; }
h2 { font-size: 14px; margin: 18px 0 5px; }
table { width: 100%; border-collapse: collapse; table-layout: fixed; }
th { color: #66716e; font-size: 11px; text-align: left; font-weight: normal; padding: 5px 6px; border-bottom: 1px solid #cdd6d2; }
td { padding: 8px 6px; border-bottom: 1px solid #e5eae7; vertical-align: top; word-wrap: break-word; overflow-wrap: anywhere; }
.rarity { width: 54px; }
.chance { width: 66px; text-align: right; white-space: nowrap; }
.rare { color: #91671f; }
.uncommon { color: #536c83; }
.common { color: #785c4c; }
.empty { margin: 16px 0; color: #66716e; }
footer { border-top: 1px solid #cdd6d2; padding-top: 10px; margin-top: 18px; color: #66716e; font-size: 11px; }
tr { page-break-inside: avoid; }
</style></head>
<body><main>
<header><div class="brand">WARFRAME · 遗物</div>
<h1 th:text="${items != null and !#lists.isEmpty(items) ? items[0].relicName : ''遗物''}">遗物</h1>
<div class="meta" th:if="${query != null and query != ''''}" th:text="${query}"></div>
</header>
<section th:each="relic : ${items}">
<div class="meta" style="margin-top: 12px">
<span th:text="${relic[''vaulted''] == null ? ''入库状态未提供'' : (relic[''vaulted''] ? ''已入库'' : ''未入库'')}"></span>
<span th:if="${relic[''quality''] != null}" th:text="${'' · '' + relic[''quality'']}"></span>
</div>
<div class="meta" th:text="${relic.detailPagination}"></div>
<h2 th:if="${relic[''rewards''] != null}">奖励</h2>
<table th:if="${relic[''rewards''] != null}">
<thead><tr><th>物品</th><th class="rarity">稀有度</th><th class="chance">概率</th></tr></thead>
<tbody><tr th:each="reward : ${relic[''rewards'']}">
<td th:text="${reward.rewardName}"></td>
<td class="rarity" th:classappend="${reward[''rarity''] == ''稀有'' ? ''rare'' : (reward[''rarity''] == ''罕见'' ? ''uncommon'' : ''common'')}" th:text="${reward[''rarity''] != null ? reward[''rarity''] : ''未提供''}"></td>
<td class="chance" th:text="${reward[''chance''] != null ? #numbers.formatDecimal(reward[''chance''], 1, 2) + ''%'' : ''未提供''}"></td>
</tr></tbody></table>
<h2 th:if="${relic[''drops''] != null}">获取地点</h2>
<table th:if="${relic[''drops''] != null}">
<thead><tr><th>地点</th><th class="chance">概率</th></tr></thead>
<tbody><tr th:each="drop : ${relic[''drops'']}">
<td th:text="${drop[''location''] != null ? drop[''location''] : ''地点未提供''}"></td>
<td class="chance" th:text="${drop[''chance''] != null ? #numbers.formatDecimal(drop[''chance''], 1, 2) + ''%'' : ''未提供''}"></td>
</tr></tbody></table>
</section>
<p class="empty" th:if="${notice != null}" th:text="${notice}"></p>
<footer><span th:text="${pagination}"></span></footer>
</main></body></html>
', 't', '2026-10-15 13:19:05.136139', '2026-10-15 13:19:05.136139'),
