    iconasset TEXT,
    iconstatus_state smallint,
    iconstatus TEXT,
    name_state smallint,
    name TEXT,
    nameen_state smallint,
    nameen TEXT,
    namekey_state smallint,
    namekey TEXT,
    namezh_state smallint,
    namezh TEXT,
    platinumcost_state smallint,
    platinumcost NUMERIC,
    uniquename_state smallint,
    uniquename TEXT
);
