    id bigint DEFAULT nextval('nnmbot.wf_official_row_id_seq') PRIMARY KEY,
    maintenance_type varchar(20) DEFAULT 'OFFICIAL' NOT NULL,
    bkey varchar(500) NOT NULL,
    official_name varchar(500),
    localized_name varchar(500),
    parent_name varchar(500),
    product_category varchar(160),
    exclude_from_codex boolean,
    description text,
    long_description text,
    wiki_slug varchar(300),
    market_slug varchar(300),
    raw_json text NOT NULL,
    localized_raw_json text,
    enabled boolean DEFAULT true NOT NULL,
    created_at timestamp without time zone NOT NULL,
    updated_at timestamp without time zone NOT NULL,
    root_state smallint,
    availablechallenges_state smallint,
    avatarurl_state smallint,
    avatarurl TEXT,
    basedrain_state smallint,
    basedrain NUMERIC,
    codexsecret_state smallint,
    codexsecret boolean,
    compat_state smallint,
    compat TEXT,
    compatibilitytags_state smallint,
    compatibleitems_state smallint,
    compatname_state smallint,
    compatname TEXT,
    compatnamezh_state smallint,
    compatnamezh TEXT,
    description_value_state smallint,
    description_value TEXT,
    descriptionen_state smallint,
    descriptionen TEXT,
    descriptionlines_state smallint,
    descriptionzh_state smallint,
    descriptionzh TEXT,
    excludefromcodex_state smallint,
    excludefromcodex boolean,
    fusionlimit_state smallint,
    fusionlimit NUMERIC,
    icon_state smallint,
    icon TEXT,
    iconasset_state smallint,
    iconasset TEXT,
    iconstatus_state smallint,
    iconstatus TEXT,
    iconurl_state smallint,
    iconurl TEXT,
    incompatibilitytags_state smallint,
    introducedat_state smallint,
    introducedat NUMERIC,
    isfrivolous_state smallint,
    isfrivolous boolean,
    isstarter_state smallint,
    isstarter boolean,
    isutility_state smallint,
    isutility boolean,
    itemreferences_state smallint,
    modset_state smallint,
    modset TEXT,
    modsetvalues_state smallint,
    name_state smallint,
    name TEXT,
    nameen_state smallint,
    nameen TEXT,
    namekey_state smallint,
    namekey TEXT,
    namezh_state smallint,
    namezh TEXT,
    polarity_state smallint,
    polarity TEXT,
    ranks_state smallint,
    rarity_state smallint,
    rarity TEXT,
    recordkey_state smallint,
    recordkey TEXT,
    subtype_state smallint,
    subtype TEXT,
    tradable_state smallint,
    tradable boolean,
    type_state smallint,
    type TEXT,
    uniquename_state smallint,
    uniquename TEXT,
    upgradeentries_state smallint,
    upgradetype_state smallint,
    upgradetype TEXT
);
