    descriptionen TEXT,
    descriptionzh_state smallint,
    descriptionzh TEXT,
    droptable_state smallint,
    droptable TEXT,
    excludefromsimulacrum_state smallint,
    excludefromsimulacrum boolean,
    faction_state smallint,
    faction TEXT,
    factionresistancekeyword_state smallint,
    factionresistancekeyword TEXT,
    health_state smallint,
    health NUMERIC,
    hitproxies_state smallint,
    icon_state smallint,
    icon TEXT,
    iconasset_state smallint,
    iconasset TEXT,
    iconstatus_state smallint,
    iconstatus TEXT,
    iconurl_state smallint,
